import json
from pathlib import Path
from collections import deque
root=Path('code/V4/runs/R65_schedule_free_full18')
for arm,name in [('A','A_constant_adamw_seed2'),('B','B_schedule_free_seed2')]:
 d=root/name
 h=json.loads((d/'history.json').read_text()) if (d/'history.json').exists() else []
 summary={'arm':arm,'completed_epochs':len(h),'result':(d/'result.json').exists()}
 if h:
  last=h[-1]; best=max(h,key=lambda r:r['val']['native_correct']); trains=[r for r in h if r.get('train')]
  summary.update(last_val_count=last['val']['native_correct'],best_val_count=best['val']['native_correct'],best_epoch=best['epoch'],retries=sum(r['optimization']['amp_retries'] for r in h))
  if trains: summary['latest_train']={'epoch':trains[-1]['epoch'],'top1':trains[-1]['train']['macro']['macro_top1']}
 if (d/'updates.jsonl').exists():
  with (d/'updates.jsonl').open() as stream: tail=deque(stream,maxlen=1)
  u=json.loads(tail[0]); summary['tail']={k:u[k] for k in ['epoch','update_in_epoch','successful_update','presentations','lr','loss','ce','kl','grad_norm','clip_coefficient','retries','peak_memory_gib']}
 print(json.dumps(summary))
PY"

